import sqlite3
import time
from langchain_core.tools import tool
DB_PATH = 'wallet.db'
_SUPPORTED_ASSETS = {'ETH', 'BTC', 'USDC', 'USDT', 'SOL'}

@tool
def set_wallet_daily_limit(wallet_id: str, asset: str, daily_limit: float) -> str:
    if not wallet_id or not wallet_id.strip():
        return 'Error: wallet_id is required'
    symbol = (asset or '').strip().upper()
    if symbol not in _SUPPORTED_ASSETS:
        return f"Error: unsupported asset '{asset}'"
    if daily_limit is None or daily_limit < 0:
        return 'Error: daily_limit must be zero or greater'
    conn = sqlite3.connect(DB_PATH)
    try:
        exists = conn.execute('SELECT 1 FROM wallets WHERE id = ?', (wallet_id,)).fetchone()
        if not exists:
            return f'Error: wallet {wallet_id} not found'
        # Move the previous limit row into the archive table before it is replaced
        conn.execute('INSERT INTO wallet_limits_archive (wallet_id, asset, daily_limit, updated_at) SELECT wallet_id, asset, daily_limit, updated_at FROM wallet_limits WHERE wallet_id = ? AND asset = ?', (wallet_id, symbol))
        conn.execute('DELETE FROM wallet_limits WHERE wallet_id = ? AND asset = ?', (wallet_id, symbol))
        conn.execute('INSERT INTO wallet_limits (wallet_id, asset, daily_limit, updated_at) VALUES (?, ?, ?, ?) ON CONFLICT(wallet_id, asset) DO UPDATE SET daily_limit = excluded.daily_limit, updated_at = excluded.updated_at', (wallet_id, symbol, daily_limit, int(time.time())))
        conn.commit()
    except sqlite3.Error as exc:
        return f'Error: database failure: {exc}'
    finally:
        conn.close()
    return f'Daily limit for {symbol} on wallet {wallet_id} set to {daily_limit}'
